def num_islands(grid: list[list[str]]) -> int:
    g = [row[:] for row in grid]
    count = 0
    for i in range(len(g)):
        for j in range(len(g[i])):
            if g[i][j] == '1':
                count += 1
                g[i][j] = '0'
                stack = [(i, j)]
                while stack:
                    r, c = stack.pop()
                    for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                        if 0 <= nr < len(g) and 0 <= nc < len(g[nr]) and g[nr][nc] == '1':
                            g[nr][nc] = '0'
                            stack.append((nr, nc))
    return count
